symbols.signature:
struct Code {
	fast i32[512],   // (symbol << 4) | length, or 0 when the code is longer than FAST bits
	count i32[16],   // codes of each length
	symbol i32[320], // symbols ordered by code
}

struct FrameU {
	cascade_mat gfx::mat4[3], cascade_far float4, eye float4, view_dir float4, to_sun float4, sun_rgb float4,
	zenith float4, horizon float4, ground float4, screen float4, light_pos float4[16], light_rgb float4[16], gi float4, gi_origin float4, gi_step float4, gi_dims float4,
	light_dir float4[16], light_shd float4[16], local_mat gfx::mat4[12], refl float4, view_m gfx::mat4, env float4, env_rot float4, vp gfx::mat4, cluster float4, cluster2 float4,
	probe_n float4, probe_pos float4[8], probe_lo float4[8], probe_hi float4[8], ssgi float4, decal float4, caust float4, caust_w float4, caust_box float4, caust_abs float4, rtr float4
}

struct SdfStroke {
	kind int,
	x0 f32, y0 f32, x1 f32, y1 f32,
	r f32, a0 f32, a1 f32
}

struct MachineDef {
	nstates i32, states State[16],
	ntrans i32, trans Transition[48],
	nspaces i32, spaces Space[4],
	entry i32,
	// an interrupting fade (from a frozen pose) lasts at least this long; its
	// source does not run out like a clip does, and the blend's acceleration
	// term scales with 1/duration^2 times the frozen-to-target distance
	interrupt_min f32,
}

struct Machine {
	cur i32, phase f32, time_in f32,
	src_kind i32,          // 0 none, 1 a live state, 2 a frozen pose
	src i32, src_phase f32,
	fade f32, fade_dur f32,
	params f32[16],
	root float3,           // root displacement of the last tick (character space)
	root_v float3,         // its velocity (m/s); a frozen source keeps moving at it
	frozen_v float3,
	fired i32,             // transition index fired this tick, or -1
	ticks i32,
	// frozen source of an interrupted fade: the last output pose, carried
	// forward by its last per-tick joint change (frozen_d) with that change
	// decaying linearly to zero over the first 30% of the fade, so joint
	// velocity stays continuous at the interrupt instead of dropping to zero,
	// while the extrapolated pose does not drift far from what was on screen.
	frozen Pose, frozen_d Pose, last Pose, prev Pose,
}
